// Input  = Open, High, Low, Close
//
// Output = int
func Cdlhangingman(open []float64, high []float64, low []float64, closePrice []float64, integerBuf []int32) (outInteger []int32) {
	if len(open) == 0 {
		panic(&TALibError{RetCode: 2, Message: retCodeMessage(2)})
	}
	if len(high) != len(open) || len(low) != len(open) || len(closePrice) != len(open) {
		panic(&TALibError{RetCode: 2, Message: retCodeMessage(2)})
	}
	lookback := int(C.TA_CDLHANGINGMAN_Lookback())
	if lookback < 0 {
		panic(&TALibError{RetCode: 2, Message: retCodeMessage(2)})
	}
	n := len(open)
	outInteger = reuseOrAllocInt32(integerBuf, n)
	fillNaNInt32(outInteger[:min(lookback, n)])
	if n <= lookback {
		return outInteger
	}
	var begIdx, nbElem C.int
	rc := C.TA_CDLHANGINGMAN(0, cInt(n-1),
		inPtr(open),
		inPtr(high),
		inPtr(low),
		inPtr(closePrice),
		&begIdx, &nbElem,
		inPtrInt(outInteger[lookback:]))
	checkRC(rc)
	if int(begIdx) != lookback {
		panic(&TALibError{RetCode: 5000, Message: retCodeMessage(5000)})
	}
	fillNaNInt32(outInteger[lookback+int(nbElem):])
	return outInteger
}

