// Zigzag - Zig Zag
//
// Input  = High, Low
//
// Output = double, int, int
//
// Parameters:
//   - sensitivity (0 to 100): Minimum move away from the current extreme that reverses the leg, in percent
//   - minTrendLength (1 to 100000): Minimum number of bars between two pivots
func Zigzag(high []float64, low []float64, sensitivity float64, minTrendLength int, zigZagBuf []float64, trendBuf []int32, pivotIdxBuf []int32) (outZigZag []float64, outTrend []int32, outPivotIdx []int32) {
	if len(high) == 0 {
		panic(&TALibError{RetCode: 2, Message: retCodeMessage(2)})
	}
	if len(low) != len(high) {
		panic(&TALibError{RetCode: 2, Message: retCodeMessage(2)})
	}
	lookback := int(C.TA_ZIGZAG_Lookback(C.double(sensitivity), cInt(minTrendLength)))
	if lookback < 0 {
		panic(&TALibError{RetCode: 2, Message: retCodeMessage(2)})
	}
	n := len(high)
	outZigZag = reuseOrAlloc(zigZagBuf, n, high, low)
	fillNaN(outZigZag[:min(lookback, n)])
	outTrend = reuseOrAllocInt32(trendBuf, n)
	fillNaNInt32(outTrend[:min(lookback, n)])
	outPivotIdx = reuseOrAllocInt32(pivotIdxBuf, n)
	fillNaNInt32(outPivotIdx[:min(lookback, n)])
	if n <= lookback {
		return outZigZag, outTrend, outPivotIdx
	}
	var begIdx, nbElem C.int
	rc := C.TA_ZIGZAG(0, cInt(n-1),
		inPtr(high),
		inPtr(low),
		C.double(sensitivity),
		cInt(minTrendLength),
		&begIdx, &nbElem,
		inPtr(outZigZag[lookback:]),
		inPtrInt(outTrend[lookback:]),
		inPtrInt(outPivotIdx[lookback:]))
	checkRC(rc)
	if int(begIdx) != lookback {
		panic(&TALibError{RetCode: 5000, Message: retCodeMessage(5000)})
	}
	fillNaN(outZigZag[lookback+int(nbElem):])
	fillNaNInt32(outTrend[lookback+int(nbElem):])
	fillNaNInt32(outPivotIdx[lookback+int(nbElem):])
	return outZigZag, outTrend, outPivotIdx
}

